WITH cleaned AS (SELECT id, account_type, balance, opened_date, status, ROUND(balance, 0) balance_rounded FROM accounts WHERE customer_id IN (32, 39)), enriched AS (SELECT id, account_type, balance, opened_date, status, balance_rounded, NTILE(4) OVER (PARTITION BY status, account_type ORDER BY balance DESC, id) balance_bucket, LAST_VALUE(status) IGNORE NULLS OVER (ORDER BY balance_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_status, RANK() OVER (PARTITION BY status, account_type ORDER BY balance DESC NULLS FIRST) balance_rank FROM cleaned), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_type, status ORDER BY balance_bucket, id) AS rn FROM enriched QUALIFY rn = 1), with_windows AS (SELECT *, LEAD(balance_rounded, 1) OVER (PARTITION BY status ORDER BY rn, id) next_balance_rounded, CUME_DIST() OVER (PARTITION BY account_type, status ORDER BY balance_rounded DESC NULLS LAST) balance_rounded_cume_dist, ROUND(balance_rank / SUM(balance_rank) OVER (PARTITION BY status), 4) balance_rank_share FROM ranked) SELECT id, balance, opened_date, status, balance_rounded, balance_bucket, last_known_status, rn, next_balance_rounded, CASE WHEN status RLIKE '^(CLOSED|FROZEN)$' THEN 'OTHER_ZONE' WHEN status RLIKE '^(OPEN)$' THEN 'CORE' ELSE 'GROUP_A' END AS status_zone FROM with_windows ORDER BY rn DESC NULLS FIRST, next_balance_rounded
